// --------------------------------------------------------------- demo beat --
// 8 bars, 140 BPM half-time: 2 bars of pad + hats (quiet), then 808, kick,
// snare, hats with rolls, pad and a plucked line. Rendered offline.
async function makeDemoBeat(sr = 44100) {
  const bpm = 140, beat = 60 / bpm, bars = 8, dur = bars * 4 * beat;
  const ctx = new OfflineAudioContext(2, Math.ceil(dur * sr), sr);
  const master = ctx.createGain(); master.gain.value = 0.8;
  const comp = ctx.createDynamicsCompressor(); comp.threshold.value = -14; comp.ratio.value = 4; comp.attack.value = 0.003; comp.release.value = 0.12;
  master.connect(comp); comp.connect(ctx.destination);
  const noise = ctx.createBuffer(1, sr, sr); { const d = noise.getChannelData(0); const r = rng(3); for (let i = 0; i < d.length; i++) d[i] = r() * 2 - 1; }
  const at = (bar, b16) => (bar * 16 + b16) * beat / 4;
  const kick = (t, v = 1) => {
    const o = ctx.createOscillator(), g = ctx.createGain(); o.frequency.setValueAtTime(160, t); o.frequency.exponentialRampToValueAtTime(48, t + 0.07);
    g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(v, t + 0.002); g.gain.exponentialRampToValueAtTime(0.001, t + 0.38);
    o.connect(g); g.connect(master); o.start(t); o.stop(t + 0.4);
  };
  const b808 = (t, f, len, glideTo) => {
    const o = ctx.createOscillator(), g = ctx.createGain(), ws = ctx.createWaveShaper();
    const cv = new Float32Array(1024); for (let i = 0; i < 1024; i++) { const x = i / 511.5 - 1; cv[i] = Math.tanh(2.2 * x); } ws.curve = cv;
    o.frequency.setValueAtTime(f, t); if (glideTo) o.frequency.exponentialRampToValueAtTime(glideTo, t + len * 0.6);
    g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(0.55, t + 0.005); g.gain.setTargetAtTime(0.0001, t + len * 0.75, len * 0.18);
    o.connect(ws); ws.connect(g); g.connect(master); o.start(t); o.stop(t + len * 1.6);
  };
  const snare = (t, v = 1) => {
    const n = ctx.createBufferSource(); n.buffer = noise; const bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 2600; bp.Q.value = 0.7;
    const g = ctx.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(0.7 * v, t + 0.001); g.gain.exponentialRampToValueAtTime(0.001, t + 0.2);
    n.connect(bp); bp.connect(g); g.connect(master); n.start(t, Math.random() * 0.5); n.stop(t + 0.25);
    const o = ctx.createOscillator(), g2 = ctx.createGain(); o.frequency.setValueAtTime(230, t); o.frequency.exponentialRampToValueAtTime(170, t + 0.08);
    g2.gain.setValueAtTime(0.45 * v, t); g2.gain.exponentialRampToValueAtTime(0.001, t + 0.12); o.connect(g2); g2.connect(master); o.start(t); o.stop(t + 0.15);
  };
  const hat = (t, v = 0.25, open = false) => {
    const n = ctx.createBufferSource(); n.buffer = noise; const hp = ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 7500;
    const g = ctx.createGain(); g.gain.setValueAtTime(v, t); g.gain.exponentialRampToValueAtTime(0.001, t + (open ? 0.22 : 0.045));
    n.connect(hp); hp.connect(g); g.connect(master); n.start(t, Math.random() * 0.8); n.stop(t + 0.3);
  };
  const pad = (t, freqs, len, v = 0.06) => {
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.setValueAtTime(700, t); lp.frequency.linearRampToValueAtTime(1500, t + len / 2); lp.frequency.linearRampToValueAtTime(800, t + len);
    const g = ctx.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(v, t + 0.4); g.gain.setValueAtTime(v, t + len - 0.4); g.gain.linearRampToValueAtTime(0, t + len);
    lp.connect(g); g.connect(master);
    for (const f of freqs) for (const dt of [-6, 5]) { const o = ctx.createOscillator(); o.type = 'sawtooth'; o.frequency.value = f; o.detune.value = dt; o.connect(lp); o.start(t); o.stop(t + len); }
  };
  const pluck = (t, f, v = 0.12) => {
    const o = ctx.createOscillator(); o.type = 'triangle'; o.frequency.value = f; const g = ctx.createGain();
    g.gain.setValueAtTime(v, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.35); o.connect(g); g.connect(master); o.start(t); o.stop(t + 0.4);
  };
  const chords = [[220, 261.6, 329.6], [174.6, 220, 261.6], [196, 246.9, 293.7], [164.8, 207.7, 246.9]];
  for (let bar = 0; bar < bars; bar++) {
    pad(at(bar, 0), chords[bar % 4], 4 * beat, bar < 2 ? 0.05 : 0.04);
    for (let s = 0; s < 16; s += 2) hat(at(bar, s), s % 4 ? 0.12 : 0.2);
    if (bar >= 2) {
      if (bar % 2 === 1) for (let s = 12; s < 16; s += 1) hat(at(bar, s) + beat / 8, 0.1);
      kick(at(bar, 0)); kick(at(bar, 10), 0.85); if (bar % 2) kick(at(bar, 14), 0.7);
      snare(at(bar, 8));
      const root = [55, 43.65, 49, 41.2][bar % 4];
      b808(at(bar, 0), root, beat * 2.4); b808(at(bar, 10), root, beat * 1.4, bar % 2 ? root * 1.5 : null);
      const mel = [440, 523.3, 659.3, 587.3, 523.3, 440, 392, 440];
      for (let s = 0; s < 8; s++) if ((s + bar) % 3 !== 1) pluck(at(bar, s * 2 + 1), mel[(s + bar) % 8] * (bar % 2 ? 1 : 0.5));
    }
  }
  return await ctx.startRendering();
}

